import {cabinet,rect,circle,text,ring} from './cabinet.js';
export function reversiFlips(b,i,who){if(b[i]||i<0||i>=36)return [];const out=[],x=i%6,y=Math.floor(i/6);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;const line=[];let xx=x+dx,yy=y+dy;while(xx>=0&&xx<6&&yy>=0&&yy<6&&b[yy*6+xx]===3-who){line.push(yy*6+xx);xx+=dx;yy+=dy;}if(line.length&&xx>=0&&xx<6&&yy>=0&&yy<6&&b[yy*6+xx]===who)out.push(...line);}return out;}
export const reversiMoves=(b,who)=>b.map((_,i)=>i).filter(i=>reversiFlips(b,i,who).length);
const apply=(b,i,who)=>{const n=[...b];for(const j of reversiFlips(b,i,who))n[j]=who;n[i]=who;return n;};
function value(b){let v=0;for(let i=0;i<36;i++){const x=i%6,y=Math.floor(i/6),w=(x===0||x===5)&&(y===0||y===5)?45:(x===1||x===4)&&(y===1||y===4)?-9:(x===0||x===5||y===0||y===5)?6:1;v+=(b[i]===2?1:b[i]===1?-1:0)*w;}return v+3*(reversiMoves(b,2).length-reversiMoves(b,1).length);}
export function chooseReversi(b){let best=-Infinity,choice=-1;for(const i of reversiMoves(b,2)){const n=apply(b,i,2),reply=reversiMoves(n,1);const score=reply.length?Math.min(...reply.map(j=>value(apply(n,j,1)))):value(n)+30;if(score>best){best=score;choice=i;}}return choice;}
export function createReversi(mount,api){const q=cabinet(mount,api,{accent:'#8ce9d0',height:440}),c=q.c;let b,turn=1,wait=0,cursor=8,last=-1;
 function reset(){b=Array(36).fill(0);b[14]=b[21]=2;b[15]=b[20]=1;turn=1;wait=0;cursor=8;last=-1;}
 function place(i){if(!q.active)return;const flips=reversiFlips(b,i,turn);if(!flips.length){q.sound('blocked');return;}b=apply(b,i,turn);last=i;q.sound('flip',Math.min(flips.length,8));q.burst(30+i%6*52,77+Math.floor(i/6)*52,'#8ce9d0',6);turn=3-turn;wait=.7;
  if(!reversiMoves(b,turn).length){turn=3-turn;if(!reversiMoves(b,turn).length){const yours=b.filter(v=>v===1).length,cpu=b.filter(v=>v===2).length;q.add(yours);q.finish(yours>cpu?'A lovely reversal.':yours===cpu?'An even split.':'The board turned.',`You ${yours} · CPU ${cpu}. Corners are worth keeping.`,yours>cpu);}else q.say(turn===1?'CPU passes. Your turn again.':'No legal move. CPU plays again.');}
 }
 reset();return {start(){reset();q.start();},tap(p){p=q.local(p);const x=Math.floor((p.x-24)/52),y=Math.floor((p.y-50)/52);if(turn===1&&x>=0&&x<6&&y>=0&&y<6)place(y*6+x);},direction(d){cursor=Math.max(0,Math.min(35,cursor+({left:-1,right:1,up:-6,down:6}[d]||0)));},action(){if(turn===1)place(cursor);},tick(dt){q.frame(dt,dt=>{if(turn===2){wait-=dt;if(wait<=0)place(chooseReversi(b));}},()=>{q.header(`YOU ${b.filter(v=>v===1).length} · CPU ${b.filter(v=>v===2).length}`,turn===1?'YOUR TURN':'THINKING…');const moves=turn===1?reversiMoves(b,1):[];b.forEach((v,i)=>{const x=24+i%6*52,y=50+Math.floor(i/6)*52;rect(c,x,y,49,49,i===cursor?'#355b60':'#203f45',6);if(v){circle(c,x+24.5,y+26,20,'#0f2429');circle(c,x+24.5,y+23,19,v===1?'#8ce9d0':'#b9acff');if(i===last)ring(c,x+24.5,y+23,13,'#ffffff88');}else if(moves.includes(i))circle(c,x+24.5,y+24.5,5,'#8ce9d0');});text(c,'Sandwich their discs to flip them.',180,393,15,'#d2e5e6');q.footer('You are mint. Dots show legal moves.');});},destroy:q.destroy};}
